//! Editing parity (ex-712).
//!
//! `tests/fixtures/editing.json` is upstream's own selection, group,
//! element creation and editing code at the pinned commit, generated by
//! `tools/goldens/editing-fixtures.mjs` on the scenes of the gestures the
//! `<excali-editor>` element wires. Every case is replayed:
//!
//! - `within`: `getElementsWithinSelection` (`selection.ts:70`) for each
//!   box, in both box selection modes, with and without
//!   `excludeElementsInFrames`;
//! - `groups`: `selectGroupsForSelectedElements` (`groups.ts:68-196`).

use excali_core::element::Element;
use excali_editor::groups::select_groups_for_selected_elements;
use excali_editor::selection::{get_elements_within_selection, BoxSelectionMode};
use excali_scene::bounds::ElementsMap;
use serde_json::{Map, Value};

const FIXTURE: &str = include_str!("fixtures/editing.json");

fn cases(kind: &str) -> Vec<Value> {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("editing.json parses");
    let cases: Vec<Value> = fixture["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .filter(|c| c["kind"] == kind)
        .cloned()
        .collect();
    assert!(!cases.is_empty(), "no {kind} cases");
    cases
}

fn elements(case: &Value) -> Vec<Element> {
    case["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .map(|e| {
            Element::from_map(e.as_object().expect("an element").clone())
                .expect("an element upstream built")
        })
        .collect()
}

fn ids(elements: &[&Element]) -> Vec<String> {
    elements.iter().map(|e| e.base.id.clone()).collect()
}

#[test]
fn elements_within_selection_match_upstream() {
    for case in cases("within") {
        let scene = elements(&case);
        let all: Vec<&Element> = scene.iter().collect();
        let map = ElementsMap::new(all.iter().copied());
        for selection in case["selections"].as_array().unwrap() {
            let b: Vec<f64> = selection["box"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_f64().unwrap())
                .collect();
            let bounds = [b[0], b[1], b[0] + b[2], b[1] + b[3]];
            for result in selection["results"].as_array().unwrap() {
                let mode = match result["mode"].as_str().unwrap() {
                    "contain" => BoxSelectionMode::Contain,
                    _ => BoxSelectionMode::Overlap,
                };
                let exclude = result["excludeElementsInFrames"].as_bool().unwrap();
                let got = ids(&get_elements_within_selection(
                    &all, bounds, &map, exclude, mode,
                ));
                let want: Vec<String> = result["ids"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_str().unwrap().to_owned())
                    .collect();
                assert_eq!(
                    got, want,
                    "{} box {b:?} {mode:?} exclude {exclude}",
                    case["id"]
                );
            }
        }
    }
}

#[test]
fn group_selection_matches_upstream() {
    for case in cases("groups") {
        let scene = elements(&case);
        let all: Vec<&Element> = scene.iter().collect();
        let selected: Map<String, Value> = case["appState"]["selectedElementIds"]
            .as_object()
            .unwrap()
            .clone();
        let editing = case["appState"]["editingGroupId"].as_str();
        let got = select_groups_for_selected_elements(&selected, editing, &all);
        let want = &case["result"];
        assert_eq!(
            Value::Object(got.selected_element_ids.clone()),
            want["selectedElementIds"],
            "{}",
            case["id"]
        );
        // key order included: the ids are an object upstream iterates
        let got_keys: Vec<&String> = got.selected_element_ids.keys().collect();
        let want_keys: Vec<&String> = want["selectedElementIds"]
            .as_object()
            .unwrap()
            .keys()
            .collect();
        assert_eq!(got_keys, want_keys, "{}", case["id"]);
        assert_eq!(
            Value::Object(got.selected_group_ids.clone()),
            want["selectedGroupIds"],
            "{}",
            case["id"]
        );
        assert_eq!(
            got.editing_group_id.as_deref(),
            want["editingGroupId"].as_str(),
            "{}",
            case["id"]
        );
    }
}
